WITH cleaned AS (SELECT id, order_id, carrier, shipped_date, delivered_date, status, CONCAT_WS(',', carrier, status) carrier_status_key, COALESCE(carrier, 'N/A') carrier_clean FROM shipments WHERE shipped_date >= DATE '2023-03-16'), latest AS (SELECT *, RANK() OVER (PARTITION BY order_id ORDER BY delivered_date DESC) AS dedup_rank FROM cleaned QUALIFY dedup_rank = 1), scored AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY dedup_rank, id) seq_no, ROW_NUMBER() OVER (PARTITION BY carrier, status ORDER BY dedup_rank, id) event_seq, FIRST_VALUE(carrier, TRUE) OVER (PARTITION BY status ORDER BY shipped_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_carrier, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY delivered_date, id) seq_no_2, FIRST_VALUE(carrier, TRUE) OVER (PARTITION BY order_id ORDER BY dedup_rank, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_carrier_2 FROM latest) SELECT CASE WHEN seq_no_2 >= 7 THEN 'HIGH' ELSE 'LOW' END AS seq_no_2_tier, SIZE(COLLECT_SET(carrier)) AS num_carriers, PERCENTILE_APPROX(seq_no, 0.5) AS seq_no_p50, SUM(CASE WHEN status = 'DELIVERED' THEN seq_no_2 ELSE 0 END) AS delivered_seq_no_2 FROM scored GROUP BY CASE WHEN seq_no_2 >= 7 THEN 'HIGH' ELSE 'LOW' END HAVING delivered_seq_no_2 >= 0
